    #[test]
    fn scrub_removes_windows_paths() {
        let input = r"Error at C:\Users\brenna\project\main.rs";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains(r"C:\Users\brenna"));
    }

    #[test]
    fn scrub_removes_tmp_paths() {
        let input = "Error at /tmp/build-abc123/output.log";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains("/tmp/build"));
    }

    #[test]
    fn scrub_removes_slack_xoxb_tokens() {
        let input = "token: xoxb-1234-abcdef-ghijkl";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("xoxb-"));
    }

    #[test]
    fn scrub_removes_slack_xoxp_tokens() {
        let input = "token: xoxp-9876-zyxwvu-tsrqpo";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("xoxp-"));
    }

    #[test]
    fn scrub_removes_gho_tokens() {
        let input = "oauth: gho_abcdefghijklmnopqrstuvwxyz1234567890";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("gho_"));
    }

    #[test]
    fn scrub_handles_empty_input() {
        let scrubbed = scrub_for_telemetry("", &HashMap::new());
        assert_eq!(scrubbed, "");
    }

    #[test]
    fn scrub_handles_empty_env() {
        let input = "safe text only";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert_eq!(scrubbed, "safe text only");
    }

    #[test]
    fn scrub_skips_empty_env_values() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "".to_string());

        let input = "nothing to mask here";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert_eq!(scrubbed, "nothing to mask here");
    }

    #[test]
    fn scrub_handles_multiple_sensitive_types_combined() {
        let mut env = HashMap::new();
        env.insert("DB_PASSWORD".to_string(), "s3cret".to_string());

        let input = "Error at /Users/dev/app: auth failed with s3cret and ghp_abcdefghijklmnopqrstuvwxyz1234567890";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert!(!scrubbed.contains("s3cret"));
        assert!(!scrubbed.contains("/Users/dev"));
        assert!(!scrubbed.contains("ghp_"));
    }

    #[test]
    fn scrub_non_secret_env_vars_not_masked() {
        let mut env = HashMap::new();
        env.insert("PATH".to_string(), "/usr/bin".to_string());
        env.insert("NODE_ENV".to_string(), "production".to_string());

        let input = "NODE_ENV=production";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert!(scrubbed.contains("production"));
    }

    #[test]
    fn scrub_truncation_boundary() {
        // Exactly at the limit should not truncate.
        // Use "err " to avoid matching the base64 token regex.
        let input = "err ".repeat(MAX_ERROR_LENGTH / 4);
        assert_eq!(input.len(), MAX_ERROR_LENGTH);
        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
        assert_eq!(scrubbed.len(), MAX_ERROR_LENGTH);
        assert!(!scrubbed.contains("[truncated]"));
    }

    #[test]
    fn scrub_truncation_one_over() {
        // One char over the limit should truncate.
        let mut input = "err ".repeat(MAX_ERROR_LENGTH / 4);
        input.push('!');
        assert_eq!(input.len(), MAX_ERROR_LENGTH + 1);
        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
        assert!(scrubbed.ends_with("...[truncated]"));
    }

    #[test]
    fn telemetry_consent_display() {
        assert_eq!(TelemetryConsent::Send.to_string(), "send");
        assert_eq!(TelemetryConsent::NoThanks.to_string(), "no_thanks");
        assert_eq!(TelemetryConsent::Always.to_string(), "always");
        assert_eq!(TelemetryConsent::Never.to_string(), "never");
    }

    #[test]
    fn telemetry_prompt_returns_always_from_user() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "always");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Always);
        assert_eq!(ui.prompts_shown(), &["telemetry_failure"]);
    }

    #[test]
    fn telemetry_prompt_returns_never_from_user() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "never");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Never);
    }

    #[test]
    fn telemetry_prompt_unknown_response_defaults_to_no_thanks() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
