        let result = prompt_telemetry(&mut ui, &report, Some("unknown_pref")).unwrap();
        assert_eq!(result, TelemetryConsent::Send);
        // A prompt should have been shown because "unknown_pref" isn't "always" or "never"
        assert_eq!(ui.prompts_shown().len(), 1);
    }

