            filename
        );
    }

    #[test]
    fn save_report_content_deserializes_back() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "cargo",
            "cargo build",
            Some(101),
            "compile error",
            "shell → retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.step_name, "cargo");
        assert_eq!(loaded.command_scrubbed, "cargo build");
        assert_eq!(loaded.exit_code, Some(101));
        assert_eq!(loaded.error_scrubbed, "compile error");
        assert_eq!(loaded.recovery_action, "shell → retry");
    }

    #[test]
    fn save_report_multiple_reports_coexist() {
        let temp = tempfile::TempDir::new().unwrap();
        let report1 = build_report("step1", "cmd1", Some(1), "", "retry", &HashMap::new());
        let report2 = build_report("step2", "cmd2", Some(2), "", "skip", &HashMap::new());

        let path1 = save_report_to(&report1, temp.path()).unwrap();
        let path2 = save_report_to(&report2, temp.path()).unwrap();

        assert!(path1.exists());
        assert!(path2.exists());
        assert_ne!(path1, path2);
    }

